import { useEffect, useRef, type ReactNode } from "react";
import { prefersReducedMotion } from "../hooks/useReducedMotion";
import "./figure.css";

/*
 * A figure from the project's illustration system.
 *
 * The SVGs in src/assets/figures/ are generated by
 * wiki/illustrations/_source/build.py — never edited by hand, so they cannot
 * drift from STYLE-GUIDE.md. They are self-contained (no <image>, no font URL,
 * no stylesheet), which is both what iGEM requires and what lets us inline them
 * here: inlined, they pick up the wiki's self-hosted Inter and Onest, and their
 * parts can be animated by the page.
 *
 * Import one with Vite's ?raw suffix and pass the string:
 *
 *   import construct from "../assets/figures/01-fusion-protein.svg?raw";
 *   <Figure svg={construct} caption="The fusion protein" draw />
 *
 * `draw` makes every stroke in the figure draw itself on first sight, left to
 * right, then the fills arrive. It is the one piece of motion applied to figures,
 * and it is skipped entirely under prefers-reduced-motion.
 */

export interface FigureProps {
  /** Raw SVG markup, imported with ?raw. */
  svg: string;
  /** Printed under the figure. Keep it to a line. */
  caption?: ReactNode;
  /** Numbered label, e.g. "Figure 3". */
  label?: string;
  /** Animate the strokes drawing themselves when the figure scrolls in. */
  draw?: boolean;
  /** Let the figure run wider than the prose column. */
  wide?: boolean;
  className?: string;
}

export function Figure({ svg, caption, label, draw = false, wide = false, className }: FigureProps) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const host = ref.current;
    if (!host) return;

    const el = host.querySelector("svg");
    if (!el) return;

    // The generated files are 1200 units wide with a height to suit; make them
    // fluid without touching the source file.
    el.removeAttribute("width");
    el.removeAttribute("height");
    el.setAttribute("preserveAspectRatio", "xMidYMid meet");

    // The generator paints a sand ground across the whole canvas, which is right
    // for the standalone sheets but reads as a card once the figure sits on a
    // band. Drop it so the drawing sits straight on the page; every band that
    // carries a figure is a light one, so the ink still reads.
    const first = el.querySelector("rect");
    const box = (el.getAttribute("viewBox") ?? "").split(/[\s,]+/).map(Number);
    if (first && box.length === 4) {
      const x = Number(first.getAttribute("x") ?? 0);
      const y = Number(first.getAttribute("y") ?? 0);
      const w = Number(first.getAttribute("width") ?? 0);
      const h = Number(first.getAttribute("height") ?? 0);
      const covers = Math.abs(w - box[2]) < 2 && Math.abs(h - box[3]) < 2
        && Math.abs(x - box[0]) < 2 && Math.abs(y - box[1]) < 2;
      if (covers) first.remove();
    }

    if (!draw || prefersReducedMotion()) {
      host.classList.add("is-in");
      return;
    }

    // Measure each stroked path once and park it at zero length.
    const strokes = Array.from(el.querySelectorAll<SVGGeometryElement>("path, line, polyline, circle"))
      .filter((p) => {
        const s = p.getAttribute("stroke");
        return !!s && s !== "none";
      });

    const lengths = strokes.map((p) => {
      let len = 0;
      try { len = p.getTotalLength(); } catch { len = 0; }
      return len;
    });

    strokes.forEach((p, i) => {
      const len = lengths[i];
      if (!len) return;
      p.style.strokeDasharray = `${len}`;
      p.style.strokeDashoffset = `${len}`;
      p.style.transition = "stroke-dashoffset 900ms cubic-bezier(.4,0,.2,1)";
      // Stagger by position across the canvas, so the figure draws left to right.
      let x = 0;
      try { x = p.getBBox().x; } catch { x = 0; }
      p.style.transitionDelay = `${Math.min(700, Math.max(0, x) * 0.45)}ms`;
    });

    const io = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting) return;
      io.disconnect();
      host.classList.add("is-in");
      strokes.forEach((p, i) => {
        if (lengths[i]) p.style.strokeDashoffset = "0";
      });
    }, { threshold: 0.25 });

    io.observe(host);
    return () => io.disconnect();
  }, [svg, draw]);

  return (
    <figure className={`wk-fig${wide ? " is-wide" : ""}${className ? ` ${className}` : ""}`}>
      {/* The markup is generated by our own build script and shipped in this
          repository — it is not user input, so inlining it is safe. */}
      <div className="wk-fig-art" ref={ref} dangerouslySetInnerHTML={{ __html: svg }} />
      {(label || caption) && (
        <figcaption>
          {label && <b>{label}. </b>}
          {caption}
        </figcaption>
      )}
    </figure>
  );
}
